## Code Example

```javascript
// Simple idempotent handler skeleton
const seen = new Set();
function handleEvent(event){
  if (seen.has(event.id)) return;
  seen.add(event.id);
  sendEmail(event.userEmail, 'Welcome!', {eventId: event.id});
}
```

